(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.EmberDynamics=api;})(globalThis,()=>{
 const collisions=typeof module==='object'&&module.exports?require('./collisions.js'):globalThis.EmberCollisions;
 const ranges={...collisions.ranges,windX:['Wind X',-1000,1000,0],windY:['Wind Y',-1000,1000,0],windZ:['Wind Z',-1000,1000,0],drag:['Air resistance',0,10,0],attraction:['Pull / push',-1000,1000,0],vortexForce:['Swirl force',-1000,1000,0],vortexLift:['Swirl lift',-500,500,0],forceX:['Force center X',-10000,10000,0],forceY:['Force center Y',-10000,10000,0],forceZ:['Force center Z',-10000,10000,0],rotationSpeed:['Particle spin (degrees / second)',-720,720,0],collisionHeight:['Collision floor height',-10000,10000,0],restitution:['Bounciness',0,1,.65],surfaceFriction:['Surface friction',0,1,.15]};
 const defaults={...collisions.defaults,...Object.fromEntries(Object.entries(ranges).map(([key,def])=>[key,def[3]])),collisionResponse:'bounce',colorOverLife:false,endColor:'#ff4f28'};
 function validate(effect){collisions.validate(effect);for(const [key,[,min,max]]of Object.entries(ranges))if(effect[key]!==undefined&&(!Number.isFinite(effect[key])||effect[key]<min||effect[key]>max))throw Error('Invalid '+key);if(effect.collisionResponse!==undefined&&!['bounce','kill'].includes(effect.collisionResponse))throw Error('Invalid collision response');if(effect.colorOverLife!==undefined&&typeof effect.colorOverLife!=='boolean')throw Error('Invalid lifetime color');if(effect.endColor!==undefined&&!/^#[0-9a-f]{6}$/i.test(effect.endColor))throw Error('Invalid end color');}
 function apply(p,dt,s){const dx=(s.forceX||0)-p.x,dy=(s.forceY||0)-p.y,dz=(s.forceZ||0)-p.z,length=Math.hypot(dx,dy,dz),radius=Math.hypot(dx,dy);let ax=s.windX||0,ay=s.windY||0,az=(s.windZ||0)+(s.vortexLift||0);if(length>1e-6){const pull=(s.attraction||0)/length;ax+=dx*pull;ay+=dy*pull;az+=dz*pull;}if(radius>1e-6){ax+=dy/radius*(s.vortexForce||0);ay-=dx/radius*(s.vortexForce||0);}const damping=Math.exp(-(s.drag||0)*dt);p.vx=(p.vx+ax*dt)*damping;p.vy=(p.vy+ay*dt)*damping;p.vz=(p.vz+az*dt)*damping;}
 return {ranges,defaults,validate,apply};
});
